const D = { density:.5, scale:1, speed:1, energy:.65, hue:135, twist:.4, warp:.45, x:.5, y:.5, style:'vector', seed:0, act:'fly' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
// ring + segment counts (density is FIRST numeric param -> obvious change at max)
const N = Math.floor(9 + P.density*17);        // 9..26 rings
const SEG = Math.floor(13 + P.density*10);      // 13..23 segments
// act dramaturgy
let rate = 0.20 + P.speed*0.30;
let wander = 0.03, twMul = 1;
if (P.act==='warp'){ rate *= (1 + K.pulse*1.4 + (K.section%2?0.5:0)); twMul = 1.4; }
else if (P.act==='drift'){ rate *= 0.55; wander = 0.06; twMul = 0.7; }
// continuous real-time fly-through (never re-phases at 8s)
const t = K.t;
const cx = P.x*width  + Math.sin(t*0.31)*u*wander + Math.sin(t*0.17+1.3)*u*wander*0.6;
const cy = P.y*height + Math.cos(t*0.26)*u*wander + Math.cos(t*0.19+0.7)*u*wander*0.6;
const focal = u*0.62*P.scale;                    // scale is SECOND numeric -> tunnel size
const punch = K.pulse*0.5 + A.bass*0.9;          // audio on top of baseline
// background trail (motion-blur streak; keeps luminance off black, never a full flash)
noStroke(); blendMode(BLEND);
if (st==='blueprint') fill(214,66,10, 26);
else fill(232,52,4, 20+P.warp*6);
rect(0,0,width,height);
// build rings, sort far -> near for correct overdraw + depth connectors
const rings = [];
for (let i=0;i<N;i++){
  const ph = ((i/N - t*rate)%1 + 1)%1;           // 0=near .. 1=far, decreasing => fly in
  const z = 0.10 + ph*4.2;
  rings.push({ ph, z, i, pts:null });
}
rings.sort((a,b)=> b.z - a.z);
const twistBase = P.twist*2.4*twMul;
const lobes = 2 + Math.floor(P.warp*4);
if (st==='vector' || st==='neon' || st==='thermal') blendMode(ADD);
let prev = null;
for (let r=0;r<rings.length;r++){
  const R = rings[r];
  const screenR = focal / R.z;
  if (screenR > u*3.5){ prev=null; continue; }    // past the camera -> skip
  const tw = R.z*twistBase + t*0.25;
  const fade = Math.min(1, 1 - R.ph*0.75);         // far rings dimmer
  const near = Math.max(0, 1 - R.z/1.1);           // near rings brighter
  let h,s,bb;
  if (st==='thermal'){ const m = 1 - R.z/4.3; h = (250 - m*250 + 360)%360; s = 84; bb = 45 + m*55; }
  else if (st==='neon'){ h = (P.hue + R.z*26 + t*22)%360; s = 90; bb = 100; }
  else if (st==='blueprint'){ h = 200; s = 55; bb = 92; }
  else { h = (P.hue + R.z*8)%360; s = 78; bb = 88; }   // vector: green wireframe
  const al = (st==='blueprint'?55:30)*(0.4+fade)*(0.6+P.energy) + near*35 + punch*20;
  strokeWeight(st==='blueprint'?1.0:(0.9 + P.energy*1.4 + near*1.2));
  stroke((h+360)%360, s, bb, Math.min(92, al));
  const pts = [];
  for (let k=0;k<=SEG;k++){
    const a = k/SEG*TWO_PI + tw;
    const lobe = 1 + P.warp*0.34*Math.sin(k*lobes + R.z*0.7 + t*1.1) + punch*0.18*Math.sin(a*3);
    const rr = screenR*lobe;
    pts.push([cx + Math.cos(a)*rr, cy + Math.sin(a)*rr]);
  }
  noFill();
  beginShape();
  for (let k=0;k<pts.length;k++) vertex(pts[k][0], pts[k][1]);
  endShape();
  if (prev && Math.abs(prev.z - R.z) < (4.2/N)*1.8){
    strokeWeight(st==='blueprint'?0.8:(0.7 + P.energy*0.8));
    for (let k=0;k<pts.length;k+=2) line(prev.pts[k][0], prev.pts[k][1], pts[k][0], pts[k][1]);
  }
  R.pts = pts;
  prev = R;
}
if (st==='blueprint'){                             // schematic center spokes
  stroke(200,55,90,40); strokeWeight(0.8);
  for (let k=0;k<8;k++){ const a=k/8*TWO_PI; line(cx,cy, cx+Math.cos(a)*u*0.5, cy+Math.sin(a)*u*0.5); }
}
blendMode(BLEND);
drawingContext.shadowBlur = 0;
